function sortInPlace(arr){
  const TH = 16;
  const swap=(a,i,j)=>{const t=a[i]; a[i]=a[j]; a[j]=t;};
  const medianOfThree=(a,i,j,k)=>{let x=[a[i],i],[a[j],j],[a[k],k].sort((p,q)=>p[0]-q[0]); return a[x[1]];};
  // iterative 3-way quicksort skeleton
  const stack=[[0,arr.length-1]];
  while(stack.length){
    const [lo,hi]=stack.pop();
    if(hi-lo+1<=TH){ // insertion sort for small partitions
      for(let i=lo+1;i<=hi;i++){
        let t=arr[i], j=i-1;
        while(j>=lo && arr[j]>t){ arr[j+1]=arr[j]; j-- }
        arr[j+1]=t;
      }
      continue;
    }
    // median-of-three pivot
    const mid=(lo+hi)>>1;
    const pivot= medianOfThree(arr, lo, mid, hi);
    // 3-way partition
    let lt=lo, i=lo, gt=hi;
    while(i<=gt){
      if(arr[i]<pivot) swap(arr, lt++, i++);
      else if(arr[i]>pivot) swap(arr, i, gt--);
      else i++;
    }
    stack.push([lo, lt-1]);
    stack.push([gt+1, hi]);
  }
}
```

## Why This Is Asked

Tests understanding of partition DP with sliding window optimization and modular arithmetic, plus dual implementation styles.

## Key Concepts

- Contiguous partitions
- Sliding window to enforce per-session bound
- Prefix-sum style accumulation for O(n) time

## Code Example

```javascript
function bottomUpCount(a, B) {
  const n = a.length, MOD = 1000000007;
  const dp = new Array(n+1).fill(0);
  dp[0] = 1;
  let left = 0, window = 0, acc = 0;
  for (let i = 1; i <= n; i++) {
    window += a[i-1];
    while (window > B) {
      window -= a[left];
      acc = (acc - dp[left] + MOD) % MOD;
      left++;
    }
    acc = (acc + dp[i-1]) % MOD;
    dp[i] = acc;
  }
  return dp[n];
}
```

